import { chromium } from 'playwright';
import { writeFileSync } from 'node:fs';
import { join } from 'node:path';

// Generate HTML with a CSS-animated SVG
const htmlContent = `
<!DOCTYPE html>
<html>
<head>
<style>
  body { margin: 0; padding: 0; background: #ffffff; display: flex; align-items: center; justify-content: center; height: 100vh; overflow: hidden; }
  svg { width: 400px; height: 800px; }
  /* We will animate between the start and end paths */
</style>
</head>
<body>
  <!-- For simplicity we use the static SVG generated by render-poses.ts, but let's animate it with a simple CSS transform or morph if possible. 
       Actually, since we want precise joint movement, let's just make the script render frame by frame and take screenshots, then use ffmpeg. -->
  <h1 style="font-family: sans-serif; position:absolute; top:20px; color:#94a3b8;">PROTOTYPE — NOT CLINICALLY REVIEWED</h1>
</body>
</html>
`;

async function main() {
  const browser = await chromium.launch();
  const context = await browser.newContext({
    recordVideo: {
      dir: 'public/exercise-media/prototypes/ex-neck-02/',
      size: { width: 640, height: 480 }
    }
  });
  const page = await context.newPage();
  
  // To get the exact pose animation, we should import pose.ts and render frames.
  const poseModule = await import('./render-poses-data.js'); // We'll create this to export the SVG string generator
  const { generateSvgForT } = poseModule;

  await page.setContent(htmlContent);

  // Animate: 4 seconds at 30 fps = 120 frames
  // 0-0.5s: hold (15 frames)
  // 0.5-1.5s: tuck (30 frames)
  // 1.5-3.0s: hold tuck (45 frames)
  // 3.0-4.0s: return (30 frames)
  
  for (let i = 0; i <= 120; i++) {
    let t = 0;
    if (i > 15 && i <= 45) {
      t = (i - 15) / 30; // 0 to 1
    } else if (i > 45 && i <= 90) {
      t = 1; // hold
    } else if (i > 90) {
      t = 1 - ((i - 90) / 30); // 1 to 0
    }
    
    // smoothstep t
    t = t * t * (3 - 2 * t);
    
    const svgContent = generateSvgForT(t);
    await page.evaluate((svg) => {
      document.body.innerHTML = '<h1 style="font-family: sans-serif; position:absolute; top:20px; color:#94a3b8;">PROTOTYPE — NOT CLINICALLY REVIEWED</h1>' + svg;
    }, svgContent);
    
    // Wait a bit to simulate framerate for the recorder, or just take screenshots and use ffmpeg
    // Taking screenshots and using ffmpeg is more reliable than recordVideo for precise frame timing.
  }

  await browser.close();
}
